package in.finseq.insurance;

import android.app.*;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;

public class ClientsActivity extends FinseqActivity {
    LinearLayout root,body,list; EditText search; JSONArray customers=new JSONArray();String balanceFilter="";
    @Override public void onCreate(Bundle b){super.onCreate(b);balanceFilter=getIntent().getStringExtra("balance_filter");if(balanceFilter==null)balanceFilter="";render();load();}
    void render(){root=Ui.column(this);Ui.appHeader(root,this,"Clients");body=Ui.contentColumn(this);root.addView(body);search=Ui.input(this,"Search name, mobile, code or family head");body.addView(search);body.addView(Ui.sub(this,"Tap a client for complete Customer 360° view."));list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){renderList();}public void afterTextChanged(Editable e){}});Ui.setScreen(this,root,1);}
    void load(){Ui.run(this,()->{try{JSONObject j=ApiClient.get(this,"/api/v1/sync");customers=j.optJSONArray("customers");if(customers==null)customers=new JSONArray();Ui.ui(this,this::renderList);}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
    void renderList(){list.removeAllViews();String q=search.getText().toString().trim().toLowerCase();int shown=0;for(int i=0;i<customers.length();i++){JSONObject c=customers.optJSONObject(i);if(c==null)continue;if(!balanceFilter.isEmpty()&&(!c.optBoolean("is_family_head")||c.optDouble(balanceFilter)<=0.01))continue;String hay=(c.optString("name")+" "+c.optString("mobile")+" "+c.optString("code")+" "+c.optString("family_head")).toLowerCase();if(!q.isEmpty()&&!hay.contains(q))continue;shown++;LinearLayout card=Ui.compactCard(this);card.setOrientation(LinearLayout.HORIZONTAL);card.setGravity(Gravity.CENTER_VERTICAL);TextView avatar=Ui.avatar(this,c.optString("name"));card.addView(avatar,new LinearLayout.LayoutParams(Ui.dp(this,52),Ui.dp(this,52)));LinearLayout txt=new LinearLayout(this);txt.setOrientation(LinearLayout.VERTICAL);txt.setPadding(Ui.dp(this,12),0,0,0);txt.addView(Ui.text(this,c.optString("name","Client"),16,true));String contact=c.optString("mobile");if(!c.optString("code").isEmpty())contact+=" · "+c.optString("code");txt.addView(Ui.sub(this,contact));txt.addView(Ui.sub(this,"Family: "+c.optString("family_head",c.optString("name"))+" · "+c.optInt("family_members",1)+" member(s)"));double due=c.optDouble("family_due"),adv=c.optDouble("family_advance");TextView balance=Ui.sub(this,(balanceFilter.equals("insurer_due")?"Insurer Due "+Ui.money(c.optDouble("insurer_due")):due>0?"Due "+Ui.money(due):"Advance "+Ui.money(adv)));balance.setTextColor(balanceFilter.equals("insurer_due")||due>0?Ui.RED:Ui.GREEN);txt.addView(balance);card.addView(txt,new LinearLayout.LayoutParams(0,-2,1));card.addView(Ui.text(this,"›",26,false));int id=c.optInt("id");card.setOnClickListener(v->startActivity(new Intent(this,Customer360Activity.class).putExtra("customer_id",id)));list.addView(card);}if(shown==0)list.addView(Ui.sub(this,"No matching client found."));}
}
